// The phase-plan executor. See run_plan.hpp.
#include "run_plan.hpp"

#include <cstdlib>
#include <filesystem>

#include <unistd.h>

#include "argv.hpp"
#include "process.hpp"
#include "repo_root.hpp"
#include "shm.hpp"
#include "state.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
std::string state_path(const std::string& workdir, size_t i) {
  return workdir + "/state-" + std::to_string(i) + ".bin";
}

const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
                                    const std::string& id) {
  for (const EngineDescriptor& e : engines)
    if (e.id == id) return &e;
  return nullptr;
}

// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
std::string resolve_plugin(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
  return default_plugin_path().string();
}

}  // namespace

LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err) {
  err.clear();
  LegTriggerArgs out;
  if (t.kind == "csr") return out;  // markers detected by plugin/vsim, not argv

  const bool fast = role == "fast-leg";
  const bool accurate = role == "accurate-leg";
  if (!fast && !accurate) return out;  // other roles carry no trigger args

  // Required-param lookup. A missing key is a caller bug; surface it (don't
  // throw) so plan_argvs can report which step failed.
  auto param = [&](const char* key) -> const std::string* {
    auto it = t.params.find(key);
    if (it == t.params.end()) {
      err = "trigger '" + t.kind + "' missing param '" + key + "'";
      return nullptr;
    }
    return &it->second;
  };

  if (t.kind == "pc") {
    if (fast) {
      if (const std::string* p = param("enter_pc"))
        out.plugin_suffix = ",enter_pc=" + *p;
    } else if (const std::string* p = param("exit_pc")) {
      out.extra = {"--hybrid-exit-pc", *p};
    }
    return out;
  }
  if (t.kind == "icount") {
    if (fast) {
      if (const std::string* p = param("qemu_icount"))
        out.plugin_suffix = ",icount=" + *p;
    } else if (const std::string* p = param("vsim_icount")) {
      out.extra = {"--hybrid-icount", *p};
    }
    return out;
  }

  err = "unknown trigger kind '" + t.kind + "'";
  return out;
}

std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
  std::vector<std::vector<std::string>> out;
  out.reserve(plan.steps.size());
  std::string prev_state_out;  // empty for the cold first leg

  for (size_t i = 0; i < plan.steps.size(); ++i) {
    const Step& step = plan.steps[i];
    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
    if (!eng) {
      err = "plan step " + std::to_string(i) + ": unknown engine '" +
            step.engine_id + "'";
      return {};
    }
    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
    if (!tmpl) {
      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
            "' has no invoke template for role '" + step.role + "'";
      return {};
    }

    std::string trig_err;
    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
    if (!trig_err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + trig_err;
      return {};
    }

    const std::string state_out = state_path(workdir, i);
    const std::map<std::string, std::string> m = {
        {"bin", eng->bin_path},
        {"elf", plan.elf},
        {"plugin", ctx.plugin_path},
        {"mmap", ctx.mmap_path},
        {"mmap_size", std::to_string(ctx.mem_size)},
        {"mmap_base", ctx.mmap_base},
        {"state_in", prev_state_out},
        {"state_out", state_out},
        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for csr)
    };
    std::vector<std::string> argv = build_argv(*tmpl, m, err);
    if (!err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + err;
      return {};
    }
    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
    // after the filled template (matches tests/e2e.sh's ordering).
    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
    out.push_back(std::move(argv));
    prev_state_out = state_out;
  }
  err.clear();
  return out;
}

PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts) {
  PlanResult res;
  if (plan.steps.empty()) {
    res.error = "plan has no steps";
    return res;
  }

  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
  std::string mmap_path = plan.mmap_path;
  const bool own_mmap = mmap_path.empty();
  if (own_mmap) {
    std::string err;
    mmap_path = allocate(plan.mem_size, err);
    if (mmap_path.empty()) {
      res.error = err;
      return res;
    }
  }

  // A private dir for the threaded drain files.
  std::error_code ec;
  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
  std::string tmpl = workdir.string();
  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
  tbuf.push_back('\0');
  const char* made = ::mkdtemp(tbuf.data());
  if (!made) {
    if (own_mmap) ::unlink(mmap_path.c_str());
    res.error = "failed to create plan work dir";
    return res;
  }
  const std::string wd = made;

  RuntimeCtx ctx;
  ctx.mmap_path = mmap_path;
  ctx.mem_size = plan.mem_size;
  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default

  std::string err;
  const std::vector<std::vector<std::string>> argvs =
      plan_argvs(plan, engines, wd, ctx, err);
  if (!err.empty()) {
    res.error = err;
  } else {
    for (size_t i = 0; i < argvs.size(); ++i) {
      const RunResult r = run_process(argvs[i], opts.timeout_ms);
      if (r.spawn_failed) {
        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
        break;
      }
      if (r.timed_out) {
        res.error = "plan step " + std::to_string(i) + ": timed out after " +
                    std::to_string(opts.timeout_ms) + " ms";
        break;
      }
      if (r.rc != opts.expect_rc) {
        res.error = "plan step " + std::to_string(i) + ": expected exit " +
                    std::to_string(opts.expect_rc) + ", got " +
                    std::to_string(r.rc);
        break;
      }
      const StateFile sf = read_state_file(state_path(wd, i));
      if (!sf.ok()) {
        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
        break;
      }
      res.phases.push_back({sf.st.mcycle, sf.st.minstret});
    }
  }

  fs::remove_all(wd, ec);
  if (own_mmap) ::unlink(mmap_path.c_str());
  return res;
}

}  // namespace andes_sim

// Subprocess helpers for andes-sim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDES_SIM_PROCESS_HPP
#define ANDES_SIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --model fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_PROCESS_HPP

// The phase-plan executor (F6) -- the C++ analog of runner.run_session, minus
// the dropped QEMU2 handback. run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDES_SIM_RUN_PLAN_HPP
#define ANDES_SIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
};

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. csr contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. csr -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. icount -> qemu
// `,icount=<qemu_icount>` / vsim `--hybrid-icount <vsim_icount>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = 200;        // drain success code (kExitHandoffToQemu)
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
};

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDES_SIM_RUN_PLAN_HPP

