  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::CsrTrigger trigger;
  const std::array<uint32_t, 1> code{encode_csrrwi(0, 0x7C0, 0)};
  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000000, [](uint8_t) { return 0u; });
  CHECK_FALSE(state.has_value());
  CHECK(bus.ops.empty());
}

TEST_CASE("HandoffController: PC-mode synthetic EXIT hit drains like CSR EXIT")
{
  // PC-trigger mode populates the trigger map via add_pc_hit() instead of
  // scan_buffer(). HandoffController must dispatch on `kind` only and not
  // depend on a recorded `insn`. This is the single-test contract the PC
  // mode relies on.
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  bus.regfile[hybrid::regno_gpr(12)] = 7;
  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000048;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000044, [](uint8_t) { return 0u; });

  REQUIRE(state);
  CHECK(state->magic == HYBRID_STATE_MAGIC);
  CHECK(state->gpr[12] == 7);
  CHECK(state->pc == 0x80000048);
}

TEST_CASE("HandoffController: PC-mode hit at unrelated PC stays silent")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::CsrTrigger trigger;
  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);

  hybrid::HandoffController h(std::move(trigger), bus);
  const auto state = h.on_retire(0x80000048, [](uint8_t) { return 0u; });
  CHECK_FALSE(state.has_value());
  CHECK(bus.ops.empty());
}

TEST_CASE("HandoffController: RUNTIME fires only when probed GPR == 1")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid::CsrTrigger trigger;
  const std::array<uint32_t, 1> code{encode_csrrw(0, 0x7C0, /*rs1=*/10)};
  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  hybrid::HandoffController h(std::move(trigger), bus);

  CHECK_FALSE(h.on_retire(0x80000000,
                          [](uint8_t r) { return r == 10 ? 0u : 0u; }));
  REQUIRE(h.on_retire(0x80000000,
                      [](uint8_t r) { return r == 10 ? 1u : 0u; }));
}

