20	// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
21	std::string state_path(const std::string& workdir, size_t i) {
22	  return workdir + "/state-" + std::to_string(i) + ".bin";
23	}
24	
25	const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
26	                                    const std::string& id) {
27	  for (const EngineDescriptor& e : engines)
28	    if (e.id == id) return &e;
29	  return nullptr;
30	}
31	
32	// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
33	std::string resolve_plugin(const std::string& override_path) {
34	  if (!override_path.empty()) return override_path;
35	  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
36	  return default_plugin_path().string();
37	}
38	
39	}  // namespace
40	
41	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
42	                                std::string& err) {
43	  err.clear();
44	  LegTriggerArgs out;
45	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
46	
47	  const bool fast = role == "fast-leg";
48	  const bool accurate = role == "accurate-leg";
49	  if (!fast && !accurate) return out;  // other roles carry no trigger args
50	
51	  // Required-param lookup. A missing key is a caller bug; surface it (don't
52	  // throw) so plan_argvs can report which step failed.
53	  auto param = [&](const char* key) -> const std::string* {
54	    auto it = t.params.find(key);
55	    if (it == t.params.end()) {
56	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
57	      return nullptr;
58	    }
59	    return &it->second;
60	  };
61	
62	  if (t.kind == "pc") {
63	    if (fast) {
64	      if (const std::string* p = param("enter_pc"))
65	        out.plugin_suffix = ",enter_pc=" + *p;
66	    } else if (const std::string* p = param("exit_pc")) {
67	      out.extra = {"--hybrid-exit-pc", *p};
68	    }
69	    return out;
70	  }
71	  if (t.kind == "icount") {
72	    if (fast) {
73	      if (const std::string* p = param("qemu_icount"))
74	        out.plugin_suffix = ",icount=" + *p;
75	    } else if (const std::string* p = param("vsim_icount")) {
76	      out.extra = {"--hybrid-icount", *p};
77	    }
78	    return out;
79	  }
80	
81	  err = "unknown trigger kind '" + t.kind + "'";
82	  return out;
83	}
84	
85	std::vector<std::vector<std::string>> plan_argvs(
86	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
87	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
88	  std::vector<std::vector<std::string>> out;
89	  out.reserve(plan.steps.size());
90	  std::string prev_state_out;  // empty for the cold first leg
91	
92	  for (size_t i = 0; i < plan.steps.size(); ++i) {
93	    const Step& step = plan.steps[i];
94	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
95	    if (!eng) {
96	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
97	            step.engine_id + "'";
98	      return {};
99	    }
100	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
101	    if (!tmpl) {
102	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
103	            "' has no invoke template for role '" + step.role + "'";
104	      return {};
105	    }
106	
107	    std::string trig_err;
108	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
109	    if (!trig_err.empty()) {
110	      err = "plan step " + std::to_string(i) + ": " + trig_err;
111	      return {};
112	    }
113	
114	    const std::string state_out = state_path(workdir, i);
115	    const std::map<std::string, std::string> m = {
116	        {"bin", eng->bin_path},
117	        {"elf", plan.elf},
118	        {"plugin", ctx.plugin_path},
119	        {"mmap", ctx.mmap_path},
120	        {"mmap_size", std::to_string(ctx.mem_size)},
121	        {"mmap_base", ctx.mmap_base},
122	        {"state_in", prev_state_out},
123	        {"state_out", state_out},
124	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
125	    };
126	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
127	    if (!err.empty()) {
128	      err = "plan step " + std::to_string(i) + ": " + err;
129	      return {};
130	    }
131	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
132	    // after the filled template (matches tests/e2e.sh's ordering).
133	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
134	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
135	    out.push_back(std::move(argv));
136	    prev_state_out = state_out;
137	  }
138	  err.clear();
139	  return out;
140	}
141	
142	PlanResult run_plan(const Plan& plan,
143	                    const std::vector<EngineDescriptor>& engines,
144	                    const PlanOptions& opts) {
145	  PlanResult res;
146	  if (plan.steps.empty()) {
147	    res.error = "plan has no steps";
148	    return res;
149	  }
150	
151	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
152	  std::string mmap_path = plan.mmap_path;
153	  const bool own_mmap = mmap_path.empty();
154	  if (own_mmap) {
