// The phase-plan executor. See run_plan.hpp.
#include "run_plan.hpp"

#include <cstdlib>
#include <filesystem>

#include <unistd.h>

#include "argv.hpp"
#include "process.hpp"
#include "repo_root.hpp"
#include "shm.hpp"
#include "state.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
std::string state_path(const std::string& workdir, size_t i) {
  return workdir + "/state-" + std::to_string(i) + ".bin";
}

const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
                                    const std::string& id) {
  for (const EngineDescriptor& e : engines)
    if (e.id == id) return &e;
  return nullptr;
}

// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
std::string resolve_plugin(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
  return default_plugin_path().string();
}

}  // namespace

LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err) {
  err.clear();
  LegTriggerArgs out;
  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv

  const bool fast = role == "fast-leg";
  const bool accurate = role == "accurate-leg";
  if (!fast && !accurate) return out;  // other roles carry no trigger args

  // Required-param lookup. A missing key is a caller bug; surface it (don't
  // throw) so plan_argvs can report which step failed.
  auto param = [&](const char* key) -> const std::string* {
    auto it = t.params.find(key);
    if (it == t.params.end()) {
      err = "trigger '" + t.kind + "' missing param '" + key + "'";
      return nullptr;
    }
    return &it->second;
  };

  if (t.kind == "pc") {
    if (fast) {
      if (const std::string* p = param("enter_pc"))
        out.plugin_suffix = ",enter_pc=" + *p;
    } else if (const std::string* p = param("exit_pc")) {
      out.extra = {"--hybrid-exit-pc", *p};
    }
    return out;
  }
  if (t.kind == "icount") {
    if (fast) {
      if (const std::string* p = param("qemu_icount"))
        out.plugin_suffix = ",icount=" + *p;
    } else if (const std::string* p = param("vsim_icount")) {
      out.extra = {"--hybrid-icount", *p};
    }
    return out;
  }

  err = "unknown trigger kind '" + t.kind + "'";
  return out;
}

std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
  std::vector<std::vector<std::string>> out;
  out.reserve(plan.steps.size());
  std::string prev_state_out;  // empty for the cold first leg

  // hw-config sync: the fast leg models the same hardware the accurate leg
  // measures, so {vlen} comes from the accurate-leg engine's descriptor.
  // 512 is the fallback for engines that report none.
  long vlen = 0;
  for (const Step& s : plan.steps)
    if (s.role == "accurate-leg")
      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
        if (e->vlen > 0) vlen = e->vlen;
  const std::string vlen_str = std::to_string(vlen > 0 ? vlen : 512);

  for (size_t i = 0; i < plan.steps.size(); ++i) {
    const Step& step = plan.steps[i];
    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
    if (!eng) {
      err = "plan step " + std::to_string(i) + ": unknown engine '" +
            step.engine_id + "'";
      return {};
    }
    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
    if (!tmpl) {
      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
            "' has no invoke template for role '" + step.role + "'";
      return {};
    }

    std::string trig_err;
    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
    if (!trig_err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + trig_err;
      return {};
    }

    const std::string state_out = state_path(workdir, i);
    const std::map<std::string, std::string> m = {
        {"bin", eng->bin_path},
        {"elf", plan.elf},
        {"plugin", ctx.plugin_path},
        {"mmap", ctx.mmap_path},
        {"mmap_size", std::to_string(ctx.mem_size)},
        {"mmap_base", ctx.mmap_base},
        {"state_in", prev_state_out},
        {"state_out", state_out},
        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
    };
    std::vector<std::string> argv = build_argv(*tmpl, m, err);
    if (!err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + err;
      return {};
    }
    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
    // after the filled template (matches tests/e2e.sh's ordering).
    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
    out.push_back(std::move(argv));
    prev_state_out = state_out;
  }
  err.clear();
  return out;
}

PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts) {
  PlanResult res;
  if (plan.steps.empty()) {
    res.error = "plan has no steps";
    return res;
  }

  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
  std::string mmap_path = plan.mmap_path;
  const bool own_mmap = mmap_path.empty();
  if (own_mmap) {
    std::string err;
    mmap_path = allocate(plan.mem_size, err);
    if (mmap_path.empty()) {
      res.error = err;
      return res;
    }
  }

  // A private dir for the threaded drain files.
  std::error_code ec;
  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
  std::string tmpl = workdir.string();
  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
  tbuf.push_back('\0');
  const char* made = ::mkdtemp(tbuf.data());
  if (!made) {
    if (own_mmap) ::unlink(mmap_path.c_str());
    res.error = "failed to create plan work dir";
    return res;
  }
  const std::string wd = made;

  RuntimeCtx ctx;
  ctx.mmap_path = mmap_path;
  ctx.mem_size = plan.mem_size;
  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default

  std::string err;
  const std::vector<std::vector<std::string>> argvs =
      plan_argvs(plan, engines, wd, ctx, err);
  if (!err.empty()) {
    res.error = err;
  } else {
    for (size_t i = 0; i < argvs.size(); ++i) {
      const RunResult r = run_process(argvs[i], opts.timeout_ms);
      if (r.spawn_failed) {
        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
        break;
      }
      if (r.timed_out) {
        res.error = "plan step " + std::to_string(i) + ": timed out after " +
                    std::to_string(opts.timeout_ms) + " ms";
        break;
      }
      if (r.rc != opts.expect_rc) {
        res.error = "plan step " + std::to_string(i) + ": expected exit " +
                    std::to_string(opts.expect_rc) + ", got " +
                    std::to_string(r.rc);
        break;
      }
      const StateFile sf = read_state_file(state_path(wd, i));
      if (!sf.ok()) {
        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
        break;
      }
      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out});
    }
  }

  fs::remove_all(wd, ec);
  if (own_mmap) ::unlink(mmap_path.c_str());
  return res;
}

}  // namespace andes_sim

#include "engine_registry.hpp"

#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>

#include <unistd.h>

#include "json.hpp"
#include "process.hpp"
#include "repo_root.hpp"

namespace fs = std::filesystem;

namespace andes_sim {

// The bundled functional engine. QEMU does not implement --describe, so its
// descriptor is built in. Binary path honors $VSIM_QEMU (matching hsim) then
// the default build location. Exposed (engine_registry.hpp) so `run --model
// fast` resolves qemu directly, skipping the directory scan + per-engine
// --describe subprocesses that whole-registry discovery would spawn.
EngineDescriptor builtin_qemu() {
  EngineDescriptor d;
  d.id = "qemu";
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = 64;
  d.triggers = {"marker", "pc", "icount", "simpoint"};
  d.roles = {"standalone", "fast-leg"};
  d.state = {"drain"};
  d.source = "built-in";
  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
  // into {state_out}, exit 200. Mirrors orchestrator/spawn.py::qemu_drain_argv
  // and tests/e2e.sh's QEMU-1 launch. {plugin}/{mmap}/{mmap_size}/{state_out}
  // are filled by the plan executor (F6); {trigger} is the trigger's plugin
  // comma-suffix (",enter_pc=.." / ",icount=N"; empty for marker), folded into the
  // single -plugin token by leg_trigger_args (F9).
  d.invoke.push_back(
      {"fast-leg",
       {"{bin}", "-object",
        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
        "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
        "enable=on,target=native", "-bios", "{elf}", "-plugin",
        "{plugin},outfile={state_out}{trigger}"}});
  // The standalone functional run (model=fast): the same andes machine as the
  // fast-leg, minus the hybrid sharing/plugin bits. run_passthrough fills
  // {bin}/{elf}; the user's post-`--` args (gdbstub, monitor, ...) append after.
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
        "{elf}"}});
  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
    d.bin_path = q;
  else
    d.bin_path = (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
  return d;
}

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

std::string read_file(const fs::path& p) {
  std::ifstream f(p, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// Ask one binary to describe itself: try `<bin> --describe`, else read the
// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
// a human-readable note in `warn`.
bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
    json::Parsed p = json::parse(r.out);
    if (p.ok) {
      std::string err = descriptor_from_json(p.value, d);
      if (err.empty()) {
        d.bin_path = bin.string();
        d.source = "--describe";
        return true;
      }
      warn = bin.string() + ": --describe JSON invalid: " + err;
    } else {
      warn = bin.string() + ": --describe output is not JSON: " + p.error;
    }
  }

  fs::path sidecar = bin;
  sidecar += ".json";
  std::error_code ec;
  if (fs::exists(sidecar, ec)) {
    json::Parsed p = json::parse(read_file(sidecar));
    if (p.ok) {
      EngineDescriptor sd;
      std::string err = descriptor_from_json(p.value, sd);
      if (err.empty()) {
        sd.bin_path = bin.string();
        sd.source = "sidecar";
        d = std::move(sd);
        return true;
      }
      warn = sidecar.string() + ": invalid descriptor: " + err;
    } else {
      warn = sidecar.string() + ": not JSON: " + p.error;
    }
  }

  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
  return false;
}

// `prefix` filters candidate basenames; empty accepts any executable. The
// default verilator/build scan passes "sim_"; a user-curated engines dir passes
// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
// lives in the call site, not in this engine-agnostic scanner.
void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
              std::set<std::string>& seen) {
  std::error_code ec;
  if (!fs::is_directory(dir, ec)) return;

  std::vector<fs::path> entries;
  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
  std::sort(entries.begin(), entries.end());  // stable, deterministic order

  for (const fs::path& p : entries) {
    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
    if (!is_executable_file(p)) continue;
    EngineDescriptor d;
    std::string warn;
    if (describe_one(p, d, warn)) {
      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
    } else if (!warn.empty()) {
      out.warnings.push_back(warn);
    }
  }
}

}  // namespace

Discovery discover_engines() {
  Discovery out;
  std::set<std::string> seen;

  EngineDescriptor qemu = builtin_qemu();
  seen.insert(qemu.id);
  out.engines.push_back(std::move(qemu));

  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
    std::stringstream ss(env);
    std::string dir;
    while (std::getline(ss, dir, ':'))
      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
  } else {
    scan_dir(repo_root() / "verilator" / "build", /*prefix=*/"sim_", out, seen);
  }
  return out;
}

}  // namespace andes_sim

